// returns the number of functions that could not be found (a GL 1.x/legacy context lacks many; only the
// ones NanoVG and the client use matter, and those are GL 2.0-3.0 plus the 1.x fixed-function calls)
extern "C" int slinky_load_gl(void *(*get)(const char *name)) {
    int missing = 0;
    for (const GlSlot &s : slots)
        if (!(*s.slot = get(s.name))) missing++;
    return missing;
}
